<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationTokenHashAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationTokenHashAccessor trait.
 *
 * Covers null default, string/VO assignment via withTokenHash,
 * getTokenHash/tokenHash accessors, and isTokenHashChanged with/without original.
 */
class UserInvitationTokenHashAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTokenHash creates a new instance with the TokenHash set
     * from a string value, and getTokenHash returns the primitive string.
     */
    public function testWithTokenHashFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationTokenHashAccessorUnitTest();

        // Act
        $result = $holder->withTokenHash('hmac-sha256:p1:cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->getTokenHash());
    }
    /**
     * Asserts that withtokenHash has access to the value object
     * from a string value, and getTokenHash returns the primitive string.
     */
    public function testWithTokenHashFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationTokenHashAccessorUnitTest();

        // Act
        $result = $holder->withTokenHash('hmac-sha256:p1:cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->tokenHash()->value());
    }
    public function testChangedTokenHash(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationTokenHashAccessorUnitTest()->withTokenHash('hmac-sha256:p1:cypher');
        $original = $holder->withTokenHash('hmac-sha256:p1:cypher');
        $same = $holder->withTokenHash('hmac-sha256:p1:cypher');
        $modified = $holder->withTokenHash('hmac-sha256:p1:ocyphered');

        // Act
        $withSame = $original->isTokenHashChanged($same);
        $withDiferent = $original->isTokenHashChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationTokenHashAccessorUnitTest
{
    use UserInvitationTokenHashAccessor;
}
